const ING_CATEGORIES={Protein:'بروتين',Carbs:'نشويات',Vegetables:'خضروات',Fruits:'فاكهة',Dairy:'ألبان',Oils:'دهون وزيوت',Legumes:'بقوليات',Bakery:'مخبوزات',Herbs:'أعشاب وتوابل',Other:'أخرى'};
